            { "Con el derecho apretado, clic izquierdo para disparar.", "With the right held, left click to fire." },
            { "Suelta: vuelve el encuadre normal", "Release: the normal framing returns" },
            { "Suelta el clic derecho: la cámara vuelve a verte por encima del hombro.", "Release the right click: the camera goes back to an over-the-shoulder view." },
            { "Basta con soltar el botón derecho.", "Just release the right button." },
            { "ARMAS: MIRA Y SONIDO PROPIOS", "WEAPONS: OWN SIGHT AND SOUND" },
            { "1 / 2 / 3 o rueda: cambias de arma", "1 / 2 / 3 or wheel: you swap weapons" },
